import SwiftUI

@main
struct RunnerApp: App {
    var body: some Scene {
        WindowGroup {
            Text("Runner")
        }
    }
}

import XCTest

final class BookFilterUITests: XCTestCase {

    func testFilterRoomsByBook() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        if app.state == .notRunning {
            app.launch()
        } else {
            app.activate()
        }

        let searchField = app.searchFields.firstMatch
        XCTAssertTrue(searchField.waitForExistence(timeout: 20), "Search field not found on All chats screen")
        searchField.tap()

        searchField.typeText("Book")

        let bookClub = app.staticTexts["Book Club"]
        XCTAssertTrue(bookClub.waitForExistence(timeout: 20), "Book Club room not visible after filtering")

        sleep(2)
    }
}

